#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing
)]
//! The blank pass (`remove_blank_text`) against upstream's `CONTROL_PARSER` reparse, one case per
//! rule of the Decisions in the Phase 6 design (`tests/output_format_cases/cases.rs`, generated by
//! `tools/parity/parity/gen_output_format_cases.py`), and the page cases of the four output formats.

#[allow(dead_code)]
mod trees;

#[path = "output_format_cases/cases.rs"]
mod cases;

use cases::{BLANK_CASES, DOC_CASES, DocCase, UPSTREAM_VERSION_TOKEN};
use std::collections::HashSet;
use trafilatura_rust::__internals::{
    Config, Extractor, Format, HtmlInput, PKG_VERSION, ParseLimits, Source, internal_extraction,
    remove_blank_text,
};
use trafilatura_rust::Call;
use trees::{ctx_for, xml_tree};

/// The output of `format` for a page with the options of the generator's `doc_case`: `fast=True`,
/// comments, `original_date`, the extensive date search of the default config, and `max_date` on the
/// call. `with_metadata` is the generator's choice for the format; XML-TEI forces it, as the
/// constructor does.
fn output_of(case: &DocCase, format: Format, with_metadata: bool) -> Option<String> {
    let mut settings = Extractor::new(
        Config::default(),
        format,
        false,
        false,
        None,
        with_metadata,
        false,
        HashSet::new(),
        HashSet::new(),
    );
    settings.url = case.url.map(str::to_string);
    settings.date_params.original_date = true;
    let call = Call::default().max_date(cases::MAX_DATE);
    internal_extraction(
        Source::Input(HtmlInput::Str(case.html)),
        case.record_id,
        &ctx_for(&settings, &call),
        &ParseLimits::default(),
    )
    .ok()
    .and_then(|document| document.text)
}

/// Asserts that `output` of every page case equals its `expected` upstream value, and names each
/// case that differs.
fn assert_doc_cases_match(
    output: impl Fn(&DocCase) -> Option<String>,
    expected: impl Fn(&DocCase) -> String,
) {
    assert!(!DOC_CASES.is_empty());
    let mut mismatches = Vec::new();
    for case in DOC_CASES {
        let got = output(case).unwrap_or_default();
        let expected = expected(case);
        if got != expected {
            mismatches.push(format!(
                "{}\nrust:     {got:?}\nupstream: {expected:?}",
                case.name
            ));
        }
    }
    assert!(
        mismatches.is_empty(),
        "{} of {} pages differ from upstream\n{}",
        mismatches.len(),
        DOC_CASES.len(),
        mismatches.join("\n")
    );
}

#[test]
fn xml_doc_cases_match_upstream() {
    assert_doc_cases_match(
        |case| output_of(case, Format::Xml, false),
        |case| case.xml.to_owned(),
    );
}

#[test]
fn xmltei_doc_cases_match_upstream() {
    assert_doc_cases_match(
        |case| output_of(case, Format::XmlTei, false),
        // the cases carry the upstream version; the header states this crate's, from Cargo.toml
        |case| case.xmltei.replace(UPSTREAM_VERSION_TOKEN, PKG_VERSION),
    );
}

#[test]
fn json_doc_cases_match_upstream() {
    assert_doc_cases_match(
        |case| output_of(case, Format::Json, false),
        |case| case.json.to_owned(),
    );
}

#[test]
fn json_meta_doc_cases_match_upstream() {
    assert_doc_cases_match(
        |case| output_of(case, Format::Json, true),
        |case| case.json_meta.to_owned(),
    );
}

#[test]
fn csv_doc_cases_match_upstream() {
    assert_doc_cases_match(
        |case| output_of(case, Format::Csv, true),
        |case| case.csv.to_owned(),
    );
}

#[test]
fn blank_cases_match_upstream() {
    assert!(!BLANK_CASES.is_empty());
    let mut mismatches = Vec::new();
    for case in BLANK_CASES {
        let mut tree = xml_tree(case.xml);
        let root = tree.root();
        if let Err(error) = remove_blank_text(&mut tree, root, &Call::default()) {
            mismatches.push(format!("{}: rust: Err({error:?})", case.name));
            continue;
        }
        let got = tree.tostring(root, true, false);
        let got = got.trim();
        if got != case.expected {
            mismatches.push(format!(
                "{}\nxml:      {:?}\nrust:     {got:?}\nupstream: {:?}",
                case.name, case.xml, case.expected
            ));
        }
    }
    assert!(
        mismatches.is_empty(),
        "{} of {} cases differ from upstream\n{}",
        mismatches.len(),
        BLANK_CASES.len(),
        mismatches.join("\n")
    );
}

#[test]
#[allow(clippy::assertions_on_constants)] // the flag is generated; this pins its value
fn buffer_split_not_kept() {
    assert!(!cases::BUFFER_SPLIT_KEPT);
}
